const b=$('Agency lead webhook').first().json.body||{}, clean=(v,n)=>String(v||'').trim().slice(0,n);
const email=clean(b.email,200).toLowerCase(), name=clean(b.name,100), message=clean(b.message,4000), requestId=clean(b.requestId,80);
const errors=[];
if(!/^[a-zA-Z0-9_-]{8,80}$/.test(requestId)) errors.push('requestId must contain 8-80 letters, digits, underscores or hyphens');
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('valid email required');
if(!name||message.length<10) errors.push('name and a message of at least 10 characters required');
if(b.website_url_confirm) errors.push('honeypot');
let domain=''; const raw=clean(b.website,250).toLowerCase();
// Only a bare HTTPS hostname is accepted. No paths, userinfo, ports, IPs or redirects.
const match=raw.match(/^(?:https:\/\/)?([a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)*\.[a-z]{2,63})\/?$/);
if(match && !/\.(local|internal|localhost|test|invalid)$/.test(match[1])) domain=match[1];
const cfg=$('Settings').first().json, allow=JSON.parse(cfg.enrichmentAllowedDomains).map(s=>String(s).toLowerCase());
return [{json:{valid:errors.length===0,errors,requestId,email,name,message,company:clean(b.company,160),domain,can_fetch:!!domain&&allow.includes(domain),website:domain?'https://'+domain:'',deal_key:'Website enquiry | '+email+' | '+requestId,received_at:new Date().toISOString()}}];

const b=$('Validate and normalise lead').first().json, cfg=$('Settings').first().json;
const r=$input.first().json;
const ok=b.can_fetch && !r.error && Number(r.statusCode)>=200 && Number(r.statusCode)<300;
const html=ok?String(r.data||r.body||'').slice(0,250000):'';
const text=html.replace(/<(script|style|noscript)\b[^>]*>[\s\S]*?<\/\1>/gi,' ').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,Number(cfg.maxWebsiteChars));
return [{json:{...b,research_ok:ok&&text.length>80,website_text:text,source_url:ok?b.website:'',research_status:!b.can_fetch?'Skipped: domain not approved':text.length>80?'Homepage fetched':'Homepage unavailable'}}];

const b=$('Prepare research evidence').first().json,c=$('Settings').first().json,a=$json.output||$json;
if(!a||typeof a!=='object'||!['purchase','research','support','spam','unknown'].includes(a.buying_intent)||typeof a.reply_draft!=='string') throw new Error('Invalid qualification schema');
const services=JSON.parse(c.services), weights=JSON.parse(c.scoreWeights), owners=JSON.parse(c.ownerByService), mentions=JSON.parse(c.slackMentionByService);
const service=services.includes(a.service)?a.service:'unknown'; const reasons=[];let score=0;
const add=(yes,k,label)=>{if(yes){score+=Number(weights[k])||0;reasons.push(label);}};
add(a.currency===c.currency&&Number(a.budget_amount)>=c.minimumBudget,'budget','Explicit budget meets minimum');
add(services.includes(service),'service','Supported service');
add(Number(a.urgency_days)>0&&Number(a.urgency_days)<=30,'urgent','Explicit deadline within 30 days');
const evidence=typeof a.website_evidence==='string'&&a.website_evidence.length>=15&&b.website_text.includes(a.website_evidence);
add(b.research_ok&&evidence,'research','Company summary has homepage evidence');
if(a.buying_intent!=='purchase'){score=Math.min(score,30);reasons.push('No explicit purchase intent; capped at 30');}
score=Math.max(0,Math.min(100,score));
const tier=a.buying_intent==='spam'?'Manual review':score>=c.qualifiedScore?'Qualified':'Needs discovery';
return [{json:{...b,service,score,tier,score_reasons:reasons.join('; ')||'No qualifying evidence',owner_id:owners[service]||owners.default,slack_member:mentions[service]||mentions.default,budget_amount:Math.max(0,Number(a.budget_amount)||0),currency:a.currency,summary:String(a.summary).slice(0,1200),company_summary:evidence?String(a.company_summary).slice(0,1000):'Not verified',reply_draft:a.reply_draft.slice(0,4000),manual_review:false}}];

